require_once __DIR__.'/../includes/auth.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['error'=>'Method not allowed'],405);verify_api_csrf();$cid=filter_var($_POST['conversation_id']??null,FILTER_VALIDATE_INT);if(!$cid||!is_member($pdo,$cid,current_user_id()))json_response(['error'=>'Not allowed'],403);if(empty($_FILES['attachment'])||$_FILES['attachment']['error']!==UPLOAD_ERR_OK)json_response(['error'=>'Choose a file smaller than 8 MB.'],422);$f=$_FILES['attachment'];if($f['size']>8*1024*1024)json_response(['error'=>'Maximum attachment size is 8 MB.'],422);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif','image/webp'=>'webp','application/pdf'=>'pdf','text/plain'=>'txt','application/zip'=>'zip','application/vnd.openxmlformats-officedocument.wordprocessingml.document'=>'docx','application/msword'=>'doc'];if(!isset($allowed[$mime]))json_response(['error'=>'File type not allowed. Use images, PDF, TXT, DOC/DOCX or ZIP.'],422);$dir=dirname(__DIR__).'/uploads/messages';if(!is_dir($dir)&&!mkdir($dir,0755,true))json_response(['error'=>'Upload folder is unavailable.'],500);$name=bin2hex(random_bytes(16)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))json_response(['error'=>'Could not save attachment.'],500);$path='uploads/messages/'.$name;$type=str_starts_with($mime,'image/')?'image':'file';$reply=filter_var($_POST['reply_to_id']??null,FILTER_VALIDATE_INT)?:null;$text=trim((string)($_POST['message']??''));$st=$pdo->prepare('INSERT INTO messages(conversation_id,sender_id,message_text,message_type,attachment_path,attachment_name,attachment_size,reply_to_id) VALUES(?,?,?,?,?,?,?,?)');$st->execute([$cid,current_user_id(),$text?:null,$type,$path,basename((string)$f['name']),$f['size'],$reply]);$mid=(int)$pdo->lastInsertId();$st=$pdo->prepare("SELECT user_id FROM conversation_members WHERE conversation_id=? AND user_id<>?");$st->execute([$cid,current_user_id()]);foreach($st->fetchAll() as $r)$pdo->prepare("INSERT INTO notifications(user_id,conversation_id,message_id,body) VALUES(?,?,?,?)")->execute([$r['user_id'],$cid,$mid,$_SESSION['full_name'].' shared an attachment']);json_response(['ok'=>true,'message_id'=>$mid]);
